package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamFitnessBank1 {
    private const val T = "ශාරීරික යෝග්‍යතාව, යෝග්‍යතා පරීක්ෂණ හා පුහුණු මූලධර්ම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("අනවශ්‍ය තෙහෙට්ටුවකින් තොරව දෛනික කාර්යයන් කාර්යක්ෂමව ඉටු කිරීමටත්, හදිසි අවස්ථාවන්ට මුහුණ දීමටත්, විවේකය ප්‍රයෝජනවත් ලෙස ගත කිරීමටත් ඇති හැකියාව කුමක්ද?", "ශාරීරික යෝග්‍යතාව (Physical Fitness)", "ක්‍රීඩා කෞශල්‍යය", "මාංශපේශී බලය පමණි", "මානසික ඒකාග්‍රතාව", "ශාරීරික යෝග්‍යතාව යනු කායිකව නිරෝගීව හා කාර්යක්ෂමව ක්‍රියාත්මක වීමට සිරුර සතු සමස්ත හැකියාවයි."),
        q("ශාරීරික යෝග්‍යතාව ප්‍රධාන වශයෙන් බෙදා වෙන් කරනු ලබන මූලික අංශ දෙක මොනවාද?", "සෞඛ්‍ය සම්බන්ධ යෝග්‍යතාව සහ කුසලතා සම්බන්ධ යෝග්‍යතාව", "දිවීම සහ පැනීම", "කායික ශක්තිය සහ මානසික ශක්තිය", "පාසල් යෝග්‍යතාව සහ වැඩිහිටි යෝග්‍යතාව", "යෝග්‍යතාව පුද්ගල සෞඛ්‍යය ආරක්ෂා කරන අංශ සහ ක්‍රීඩා දක්ෂතා වැඩිදියුණු කරන කුසලතා අංශ ලෙස දෙකොටසකි."),
        q("නිරෝගී දිවිපැවැත්මක් සහ බෝ නොවන රෝගවලින් තොරවීම සඳහා වැදගත් වන 'සෞඛ්‍ය සම්බන්ධ යෝග්‍යතා සංඝටක' ගණන කීයද?", "සංඝටක 5කි", "සංඝටක 6කි", "සංඝටක 3කි", "සංඝටක 10කි", "හෘද ස්වසන විඳදරාගැනීම, පේශි ශක්තිය, පේශි විඳදරාගැනීම, නම්‍යශීලීතාව සහ දේහ සංයුතිය සෞඛ්‍ය සංඝටක 5යි."),
        q("ක්‍රීඩා කාර්යසාධනය සහ ක්‍රීඩා කුසලතා ඉහළ නැංවීමට මූලික වන 'කුසලතා සම්බන්ධ යෝග්‍යතා සංඝටක' ගණන කීයද?", "සංඝටක 6කි", "සංඝටක 5කි", "සංඝටක 4කි", "සංඝටක 8කි", "කඩිසරතාව, සමබරතාව, සමායෝජනය, ජවය (බලය), ප්‍රතිචාර කාලය සහ වේගය කුසලතා සංඝටක 6 වේ."),
        q("දීර්ඝ වේලාවක් වෙහෙසට පත් නොවී මුළු ශරීරයම යොදවා මධ්‍යම හෝ දැඩි ව්‍යායාමවල නිරත වීමට හෘදයට සහ පෙනහළුවලට ඇති හැකියාව කුමක්ද?", "හෘද ස්වසන විඳදරාගැනීම (Cardiorespiratory Endurance)", "පේශි ශක්තිය", "කඩිසරතාව", "ප්‍රතිචාර කාලය", "හෘදය, රුධිර නාල හා පෙනහළු මගින් සක්‍රීය පේශි වෙත අඛණ්ඩව ඔක්සිජන් සැපයීමේ හැකියාවයි."),
        q("බාහිර ප්‍රතිරෝධයකට එරෙහිව මාංශපේශියක් හෝ පේශි සමූහයක් මගින් එක් වරකදී යෙදිය හැකි උපරිම බලය හඳුන්වන්නේ කෙසේද?", "මාංශපේශී ශක්තිය (Muscular Strength)", "පේශි විඳදරාගැනීම", "නම්‍යශීලීතාව", "වේගය", "බරක් එක් වරක් පමණක් එසවීමේදී (1RM) යොදන උපරිම බලය පේශි ශක්තියයි."),
        q("තෙහෙට්ටුවට පත් නොවී දීර්ඝ වේලාවක් නැවත නැවතත් මධ්‍යම ප්‍රමාණයේ බරක් එසවීමට හෝ පේශි හැකිලීමට ඇති හැකියාව කුමක්ද?", "මාංශපේශී විඳදරාගැනීම (Muscular Endurance)", "පේශි ශක්තිය", "ජවය", "සමබරතාව", "පුෂ්-අප්ස් හෝ සිට්-අප්ස් වැඩි වාර ගණනක් සිදුකිරීම පේශි විඳදරාගැනීමට නිදසුනකි."),
        q("ශරීරයේ සන්ධියක් හෝ සන්ධි සමූහයක් වේදනාවකින් තොරව සම්පූර්ණ චලන පරාසය (Range of Motion) තුළ චලනය කිරීමේ හැකියාව කුමක්ද?", "නම්‍යශීලීතාව (Flexibility)", "කඩිසරතාව", "සමායෝජනය", "දේහ සංයුතිය", "නම්‍යශීලී බව මගින් මාංශපේශී හා බන්ධනී ඇදීම් වළක්වා ක්‍රීඩා ආබාධ අවම කරයි."),
        q("මිනිස් සිරුරේ අඩංගු මුළු මේද ස්කන්ධය සහ මේද-නොවන කෙට්ටු පටක (අස්ථි, පේශි, ජලය) අතර පවතින අනුපාතය කුමක්ද?", "දේහ සංයුතිය (Body Composition)", "ශරීර බර පමණි", "ශරීර උස", "ජෛව ධාරිතාව", "දේහ සංයුතිය මගින් සිරුරේ කෙට්ටු ස්කන්ධයට සාපේක්ෂව ඇති මේද ප්‍රතිශතය විග්‍රහ කෙරේ."),
        q("ශරීරයේ සමබරතාවය සහ පාලනය නොබිඳිමින් ශීඝ්‍රයෙන් සහ නිවැරදිව දිශාව වෙනස් කිරීමට ඇති හැකියාව කුමක්ද?", "කඩිසරතාව (Agility)", "වේගය", "ප්‍රතිචාර කාලය", "ජවය", "පාපන්දු, පැසිපන්දු හා බැඩ්මින්ටන් වැනි ක්‍රීඩාවලදී ප්‍රතිවාදියා මඟහැර දිශාව මාරු කිරීමට කඩිසරතාව අත්‍යවශ්‍ය වේ."),
        q("නිශ්චලව සිටින විට හෝ චලනය වන විට ශරීරයේ ගුරුත්ව කේන්ද්‍රය ආධාරක පාදම මත රඳවා ගැනීමේ හැකියාව කුමක්ද?", "සමබරතාව (Balance)", "සමායෝජනය", "නම්‍යශීලීතාව", "ශක්තිය", "සමබරතාව ස්ථිතික සමබරතාව (නිශ්චලව සිටින විට) සහ ගතික සමබරතාව (චලනය වන විට) ලෙස දෙයාකාරය."),
        q("ඇස්, අත්, පාද වැනි සංවේදක ඉන්ද්‍රියයන් සහ ශරීර අවයව එක්ව සුමට හා නිවැරදි චලනයක් ඇති කිරීමේ හැකියාව කුමක්ද?", "සමායෝජනය (Coordination)", "කඩිසරතාව", "ජවය", "වේගය", "ටෙනිස් හෝ ක්‍රිකට් ක්‍රීඩාවේදී පන්දුව දෙස බලා පිත්තෙන් නිවැරදිව පහරදීම ඇස්-අත් සමායෝජනයට නිදසුනකි."),
        q("ශක්තිය සහ වේගය ඒකාබද්ධ කරමින් ක්ෂණිකව පුපුරන සුලු උපරිම බලයක් මුදාහැරීමේ හැකියාව කුමක්ද?", "ජවය හෙවත් බලය (Power)", "පේශි විඳදරාගැනීම", "නම්‍යශීලීතාව", "ප්‍රතිචාර කාලය", "උස පැනීම, දුර පැනීම හෝ යගුලිය දැමීමේදී ක්ෂණිකව යොදන බලය ජවය (Power = Force × Speed) වේ."),
        q("බාහිර උත්තේජනයක් ලැබුණු මොහොතේ සිට එයට ප්‍රතිචාර දැක්වීම ආරම්භ කිරීමට ගතවන කෙටි කාල පරතරය කුමක්ද?", "ප්‍රතිචාර කාලය (Reaction Time)", "චලන කාලය", "වේගය", "කඩිසරතාව", "කෙටි දුර ධාවනයේදී ආරම්භක වෙඩි හඬ ඇසුණු සැනින් ආරම්භක කුට්ටියෙන් ඉදිරියට පැනීමට ගතවන කාලයයි."),
        q("කෙටිම කාලයක් තුළ නිශ්චිත දුරක් ශරීරය හෝ ශරීර කොටසක් ගමන් කරවීමේ හැකියාව කුමක්ද?", "වේගය (Speed)", "විඳදරාගැනීම", "කඩිසරතාව", "සමබරතාව", "මීටර් 100 කෙටි දුර ධාවනය වේගය මැනීම සඳහා ප්‍රධානතම නිදසුනකි."),
        q("හෘද ස්වසන විඳදරාගැනීම මැනීම සඳහා අඟල් 20ක් (කාන්තාවන්ට අඟල් 16ක්) උස බංකුවක් මත මිනිත්තු 5ක් පියවර තබන පරීක්ෂණය කුමක්ද?", "හාවඩ් පියගැට පරීක්ෂණය (Harvard Step Test)", "කූපර් පරීක්ෂණය", "ෂටල් ධාවනය", "සිට් ඇන්ඩ් රීච්", "මිනිත්තුවකට පියවර 30 බැගින් මිනිත්තු 5ක් බංකුව නැග බැසීමෙන් පසු හෘද ස්පන්දන වේගය මැන යෝග්‍යතා දර්ශකය ගණනය කරයි."),
        q("හාවඩ් පියගැට පරීක්ෂණයේදී ශාරීරික යෝග්‍යතා දර්ශකය (Fitness Index) ගණනය කරනු ලබන නිවැරදි සූත්‍රය කුමක්ද?", "(ව්‍යායාම කාලය තත්පර වලින් × 100) / (2 × විවේක කාලයේ ස්පන්දන එකතුව)", "(කාලය × ස්පන්දනය) / 100", "(ස්පන්දන එකතුව × 100) / කාලය", "කාලය / ස්පන්දන අනුපාතය", "පරීක්ෂණයෙන් පසු මිනිත්තු 1-1.5, 2-2.5, 3-3.5 අතර ස්පන්දන තුනෙහි එකතුව යොදා ගණනය කරයි."),
        q("හෘද ස්වසන විඳදරාගැනීම සහ උපරිම ඔක්සිජන් පරිභෝජන ධාරිතාව (VO2 max) මැනීම සඳහා මිනිත්තු 12ක් පුරා උපරිම දුරක් ධාවනය කරන පරීක්ෂණය කුමක්ද?", "කූපර් මිනිත්තු 12 ධාවන පරීක්ෂණය (Cooper Test)", "හාවඩ් පරීක්ෂණය", "බීප් පරීක්ෂණය", "මීටර් 50 ධාවනය", "කෙනත් කූපර් විසින් හඳුන්වා දුන් මෙම පරීක්ෂණයේදී මිනිත්තු 12 තුළ ආවරණය කළ මුළු දුර මනිනු ලබයි."),
        q("මීටර් 20ක සීමිත දුරක් තුළ නිකුත් වන ශබ්ද සංඥාවලට (Beeps) අනුකූලව වේගය වැඩි කරමින් ධාවනය කරන බහු-අදියර විඳදරාගැනීමේ පරීක්ෂණය කුමක්ද?", "බීප් පරීක්ෂණය හෙවත් බහු-අදියර ෂටල් ධාවනය (Beep Test)", "හාවඩ් පරීක්ෂණය", "ඉලිනොයිස් පරීක්ෂණය", "රූලර් පරීක්ෂණය", "Beep test මගින් ක්‍රීඩකයාගේ උපරිම හෘද ස්වසන යෝග්‍යතාව (VO2 max) නිවැරදිව තක්සේරු කරයි."),
        q("කොඳු ඇට පෙළේ පහළ ප්‍රදේශයේ සහ කලවා පිටුපස හැම්ස්ට්‍රිං මාංශපේශීවල නම්‍යශීලීතාව මැනීමට යොදාගන්නා සම්මත පරීක්ෂණය කුමක්ද?", "ඉදිරියට නැමී ළඟාවීමේ පරීක්ෂණය (Sit and Reach Test)", "තල්ලු කිරීමේ පරීක්ෂණය", "උඩුකුරු වැතිර නැගී සිටීම", "ස්ටෝක් පරීක්ෂණය", "විශේෂිත පෙට්ටියක් ආධාරයෙන් පාද කෙළින් තබා ඉදිරියට නැමී දෑත් ළඟා කළ හැකි උපරිම දුර සෙන්ටිමීටරවලින් මනියි."),
        q("උදරීය මාංශපේශීවල ශක්තිය සහ විඳදරාගැනීම මැනීම සඳහා මිනිත්තුවක් තුළ සිදුකරන සම්මත පරීක්ෂණය කුමක්ද?", "උඩුකුරු වැතිර නැගී සිටීම (Curl-ups / Bent-knee Sit-ups)", "පුෂ්-අප්ස්", "සිට් ඇන්ඩ් රීච්", "සිරස් පැනීම", "දණහිස් නවා උඩුකුරුව වැතිර මිනිත්තුවක් තුළ සිදුකරන නිවැරදි කර්ල්-අප්ස් සංඛ්‍යාව ගණනය කරයි."),
        q("පපුවේ පේශි (පෙක්ටොරාලිස්) සහ අතේ ත්‍රිශීර්ෂික (ට්‍රයිසෙප්ස්) පේශිවල ශක්තිය හා විඳදරාගැනීම මනිනු ලබන පරීක්ෂණය කුමක්ද?", "තල්ලු කිරීම් හෙවත් පුෂ්-අප්ස් පරීක්ෂණය (Push-ups Test)", "සිට්-අප්ස්", "සිරස් පැනීම", "බීප් පරීක්ෂණය", "ශරීරය කෙළින් තබා වැලමිට අංශක 90ට නමමින් සිදුකරන උපරිම තල්ලු කිරීම් සංඛ්‍යාව මෙහිදී මනියි."),
        q("පාදවල මාංශපේශීවල ක්ෂණික ජවය හෙවත් පුපුරන සුලු බලය (Explosive Leg Power) මැනීමට සිදුකරන සිරස් පැනීමේ පරීක්ෂණය කුමක්ද?", "සාජන්ට් පැනීමේ පරීක්ෂණය හෙවත් සිරස් පැනීම (Vertical Jump Test)", "සිට් ඇන්ඩ් රීච්", "මීටර් 10 ෂටල්", "ස්ටෝක් පරීක්ෂණය", "නැගී සිට අත දිගු කළ උස සහ ඉහළට පැන ස්පර්ශ කළ උපරිම උස අතර වෙනස සෙන්ටිමීටරවලින් මනියි."),
        q("පාදවල තිරස් මාංශපේශී ජවය මැනීම සඳහා ආරම්භක රේඛාවේ සිට ඉදිරියට පනින පරීක්ෂණය කුමක්ද?", "සිටගෙන දුර පැනීමේ පරීක්ෂණය (Standing Broad Jump)", "සිරස් පැනීම", "තුන්පිම්ම", "උස පැනීම", "ධාවනයකින් තොරව සිටගෙන දෙපා එකවර යොදා ඉදිරියට පනින උපරිම දුර මෙහිදී මනිනු ලබයි."),
        q("ශරීරයේ කඩිසරතාව (Agility) මැනීම සඳහා ලී කුට්ටි දෙකක් එහා මෙහා ගෙන යමින් සිදුකරන සම්මත පරීක්ෂණය කුමක්ද?", "මීටර් 10 × 4 ෂටල් ධාවන පරීක්ෂණය (10m Shuttle Run)", "මීටර් 50 ධාවනය", "කූපර් පරීක්ෂණය", "හාවඩ් පරීක්ෂණය", "මීටර් 10ක් ඈතින් ඇති ලී කුට්ටි දෙක එකින් එක වේගයෙන් රැගෙන ඒමට ගතවන කාලය මනියි."),
        q("ක්‍රීඩකයෙකුගේ ස්ථිතික සමබරතාවය (Static Balance) මැනීම සඳහා එක් පාදයකින් සිටගෙන අනෙක් පාදය දණහිස මත තබා ඇස් පියා සිදුකරන පරීක්ෂණය කුමක්ද?", "කොක් ගසන ඉරියව් පරීක්ෂණය (Stork Stand Test)", "ඉලිනොයිස් පරීක්ෂණය", "රූලර් පරීක්ෂණය", "සිට් ඇන්ඩ් රීච්", "විලුඹ ඔසවා කොකෙකු මෙන් තනි පාදයෙන් සමබරව සිටිය හැකි උපරිම තත්පර ගණන මනිනු ලබයි."),
        q("පුද්ගලයෙකුගේ ඇස්-අත් ප්‍රතිචාර කාලය (Reaction Time) තක්සේරු කිරීම සඳහා භාවිත කරන සරල උපකරණ පරීක්ෂණය කුමක්ද?", "රූලර් ඇදවැටීමේ පරීක්ෂණය (Ruler Drop Test)", "ස්ටොප් වොච් පරීක්ෂණය", "බීප් පරීක්ෂණය", "සාජන්ට් පරීක්ෂණය", "අතහැර දැමූ සෙන්ටිමීටර 30ක රූලරය ඇඟිලි දෙකෙන් අල්ලා ගන්නා දුර ප්‍රමාණය අනුව ප්‍රතිචාර කාලය තීරණය කරයි."),
        q("ක්‍රීඩකයෙකුගේ උපරිම ධාවන වේගය (Speed) මැනීම සඳහා පාසල් මට්ටමේ බහුලව යොදාගන්නා පරීක්ෂණය කුමක්ද?", "මීටර් 30 හෝ මීටර් 50 කෙටි දුර ධාවන පරීක්ෂණය (Sprint Test)", "කූපර් පරීක්ෂණය", "හාවඩ් පරීක්ෂණය", "බීප් පරීක්ෂණය", "උපරිම වේගයෙන් කෙටි දුරක් ධාවනය කිරීමට ගතවන කාලය තත්පරවලින් නිවැරදිව මනිනු ලැබේ."),
        q("ශරීරයේ දේහ සංයුතිය සහ මේද ප්‍රතිශතය මැනීම සඳහා සමේ නැමුම් ඝනකම මනින උපකරණය කුමක්ද?", "ස්කින්ෆෝල්ඩ් කැලිපරය (Skinfold Caliper)", "ස්පයිරෝමීටරය", "ස්ෆිග්මෝමනෝමීටරය", "තර්මෝමීටරය", "ට්‍රයිසෙප්ස්, උදරය, උපඅංශඵලකය වැනි ස්ථානවල සම යට මේද ඝනකම මැන මුළු දේහ මේදය ගණනය කරයි."),
        q("යෝග්‍යතා පුහුණු සැලැස්මක් සකස් කිරීමේදී යොදාගන්නා 'FITT' මූලධර්මයේ අකුරු හතරෙන් නිරූපණය වන සංකල්ප මොනවාද?", "Frequency (සංඛ්‍යාතය), Intensity (තීව්‍රතාව), Time (කාලය), Type (වර්ගය)", "Fitness, Intelligence, Training, Time", "Fast, Intensive, Tough, Testing", "Force, Inertia, Tension, Temperature", "පුහුණු සැසි ගණන, වෙහෙසෙන ප්‍රමාණය, කාලසීමාව සහ ක්‍රියාකාරකම් වර්ගය FITT මූලධර්මයයි."),
        q("FITT මූලධර්මයේ 'Frequency' හෙවත් සංඛ්‍යාතය යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "සතියක් තුළ ව්‍යායාම හෝ පුහුණු සැසිවල නිරත වන දින ගණන", "ව්‍යායාම කරන වේගය", "එක් සැසියක ගතවන විනාඩි ගණන", "ව්‍යායාම කරන ක්‍රීඩා වර්ගය", "සාමාන්‍ය සෞඛ්‍ය සම්පන්න යෝග්‍යතාව සඳහා සතියකට අවම වශයෙන් දින 3-5ක් ව්‍යායාම නිර්දේශ කෙරේ."),
        q("FITT මූලධර්මයේ 'Intensity' හෙවත් තීව්‍රතාව යන්නෙන් මනිනු ලබන්නේ කුමක්ද?", "ව්‍යායාමයේදී පුද්ගලයා කොපමණ වෙහෙසක් හෝ බරක් දරන්නේද යන්න", "ව්‍යායාම කරන කාලය", "ව්‍යායාම කරන සති ගණන", "ක්‍රීඩාංගණයේ ප්‍රමාණය", "හෘද ස්පන්දන වේගයේ ප්‍රතිශතයක් ලෙස හෝ ඔසවන බරෙහි ප්‍රතිශතයක් ලෙස තීව්‍රතාව මනිනු ලබයි."),
        q("FITT මූලධර්මයේ 'Time' හෙවත් කාලය යන්නෙන් අදහස් වන්නේ කුමක්ද?", "එක් ව්‍යායාම සැසියක් සඳහා වැය කරන සම්පූර්ණ කාලසීමාව (මිනිත්තු)", "ව්‍යායාම කරන වේලාව උදෑසනද සවසද යන්න", "ව්‍යායාම කරන වසර ගණන", "විවේක ගන්නා දින ගණන", "හෘද ස්වසන යෝග්‍යතාව සඳහා දිනකට අවම වශයෙන් මිනිත්තු 30-60ක අඛණ්ඩ ව්‍යායාම නිර්දේශ කෙරේ."),
        q("FITT මූලධර්මයේ 'Type' හෙවත් වර්ගය යන්නෙන් අදහස් වන්නේ කුමක්ද?", "යෝග්‍යතාව සංවර්ධනය කරගැනීමට තෝරාගන්නා නිශ්චිත ක්‍රියාකාරකම හෝ ව්‍යායාම ක්‍රමය", "පුහුණුකරුගේ වර්ගය", "ක්‍රීඩා ඇඳුම් වර්ගය", "ආහාර වර්ගය", "ධාවනය, පිහිනීම, බර එසවීම, යෝග ව්‍යායාම ආදී වශයෙන් තෝරාගන්නා ක්‍රියාකාරකම මෙයින් අදහස් වේ."),
        q("ශාරීරික යෝග්‍යතාව වර්ධනය කර ගැනීමට නම් ශරීරය සාමාන්‍යයෙන් හුරුපුරුදු බරට වඩා වැඩි බරක් හෝ ආතතියක් යෙදිය යුතු බව පවසන මූලධර්මය කුමක්ද?", "අතිභාර මූලධර්මය (Overload Principle)", "විශිෂ්ටතා මූලධර්මය", "ප්‍රතිවර්ත්‍යතා මූලධර්මය", "විවිධත්වයේ මූලධර්මය", "ශරීර පද්ධති නව ඉහළ මට්ටමකට හැඩගැසීමට නම් සාමාන්‍ය සීමාව ඉක්මවා අතිභාරයක් ලබාදිය යුතුය."),
        q("ශරීරය අතිභාරයට හුරු වූ පසු යෝග්‍යතාව තවදුරටත් ඉහළ නැංවීමට නම් කාලයත් සමග ක්‍රමයෙන් භාරය වැඩි කළ යුතු බව පවසන මූලධර්මය කුමක්ද?", "ප්‍රගතිශීලී බවේ මූලධර්මය (Progression Principle)", "ප්‍රතිවර්ත්‍යතා මූලධර්මය", "විශිෂ්ටතා මූලධර්මය", "තනි පුද්ගල මූලධර්මය", "එකවර අධික බර නොයොදා ක්‍රමානුකූලව තීව්‍රතාව හෝ කාලය වැඩි කිරීම ආබාධ වළක්වයි."),
        q("යම් නිශ්චිත ක්‍රීඩාවකට හෝ ඉසව්වකට අවශ්‍ය පේශි සහ යෝග්‍යතා සංඝටක ඉලක්ක කරගෙනම පුහුණු විය යුතු බව දක්වන මූලධර්මය කුමක්ද?", "විශිෂ්ටතා මූලධර්මය (Specificity Principle)", "අතිභාර මූලධර්මය", "ප්‍රතිවර්ත්‍යතා මූලධර්මය", "විවේකයේ මූලධර්මය", "පිහිනුම් ශූරයෙකු වීමට පිහිනීමද කෙටි දුර ධාවකයෙකු වීමට ස්ප්‍රින්ට් පුහුණුවද කළ යුතුය."),
        q("පුහුණුවීම් නැවැත්වූ විට හෝ අඩු කළ විට ලබාගත් යෝග්‍යතා මට්ටම ක්‍රමයෙන් පිරිහී පෙර තත්ත්වයට පත්වන බව දක්වන මූලධර්මය කුමක්ද?", "ප්‍රතිවර්ත්‍යතා මූලධර්මය (Reversibility Principle)", "අතිභාර මූලධර්මය", "ප්‍රගතිශීලී මූලධර්මය", "විශිෂ්ටතා මූලධර්මය", "'භාවිත නොකරන්නේ නම් අහිමි වේ' (Use it or lose it) යන සංකල්පය මින් පැහැදිලි කෙරේ."),
        q("පුහුණුවීම්වලදී මානසික ඒකාකාරී බව (කම්මැලිකම) සහ අධිපුහුණුව වැළැක්වීම සඳහා විවිධ පුහුණු ක්‍රම මාරුවෙන් මාරුවට යොදාගැනීමේ මූලධර්මය කුමක්ද?", "විවිධත්වයේ මූලධර්මය (Variety Principle)", "අතිභාර මූලධර්මය", "විශිෂ්ටතා මූලධර්මය", "ප්‍රතිවර්ත්‍යතා මූලධර්මය", "විවිධ ව්‍යායාම ක්‍රම (Fartlek, Circuit, Interval) මාරු කිරීමෙන් ක්‍රීඩකයාගේ උනන්දුව අඛණ්ඩව රඳවා ගත හැක."),
        q("පුද්ගලයන්ගේ වයස, ස්ත්‍රී/පුරුෂභාවය, ජානමය හැකියාවන් සහ යෝග්‍යතා මට්ටම් අනුව පුහුණු වැඩසටහන් වෙනස් විය යුතු බව දක්වන මූලධර්මය කුමක්ද?", "තනි පුද්ගල වෙනස්කම්වල මූලධර්මය (Individuality Principle)", "අතිභාර මූලධර්මය", "විශිෂ්ටතා මූලධර්මය", "ප්‍රගතිශීලී මූලධර්මය", "සෑම ක්‍රීඩකයෙකුම එකම පුහුණු භාරයට එකම ආකාරයෙන් ප්‍රතිචාර නොදක්වයි."),
        q("පුහුණුවෙන් පසු මාංශපේශී ප්‍රතිසංස්කරණය වීමට සහ අනුවර්තනය සිදුවීමට කාලය ලබාදීම අත්‍යවශ්‍ය බව පවසන මූලධර්මය කුමක්ද?", "විවේකය සහ යථා තත්ත්වයට පත්වීමේ මූලධර්මය (Rest and Recovery)", "අඛණ්ඩ පුහුණු මූලධර්මය", "අතිභාර මූලධර්මය", "වේගවත් මූලධර්මය", "මාංශපේශී ශක්තිමත් වී වර්ධනය වන්නේ ව්‍යායාම කරන මොහොතේ නොව විවේකය සහ නින්ද ලබන විටදීය."),
        q("පුද්ගලයෙකුගේ උපරිම හෘද ස්පන්දන වේගය (Maximum Heart Rate - MHR) ගණනය කරනු ලබන සම්මත සූත්‍රය කුමක්ද?", "MHR = 220 — වයස (අවුරුදු)", "MHR = 200 + වයස", "MHR = වයස × 10", "MHR = 150 — බර", "වයස අවුරුදු 16ක සිසුවෙකුගේ උපරිම හෘද ස්පන්දන වේගය මිනිත්තුවට වාර 204ක් (220 - 16 = 204 bpm) වේ."),
        q("හෘද ස්වසන යෝග්‍යතාව වර්ධනය කර ගැනීම සඳහා පුහුණුවීම් කළ යුතු 'ඉලක්කගත හෘද ස්පන්දන කලාපය' (Target Heart Rate Zone) කුමක්ද?", "උපරිම හෘද ස්පන්දන වේගයෙන් 60% සිට 85% දක්වා", "උපරිම වේගයෙන් 10% සිට 20% දක්වා", "උපරිම වේගයෙන් 95% සිට 100% දක්වා අඛණ්ඩව", "උපරිම වේගයෙන් 30% සිට 40% දක්වා", "මෙම හද ගැස්ම පරාසයේ (60%-85%) ව්‍යායාම කිරීමෙන් හෘදය හා පෙනහළු උපරිම කාර්යක්ෂමතාවයෙන් ශක්තිමත් වේ."),
        q("ඕනෑම ප්‍රධාන ක්‍රීඩා පුහුණුවකට හෝ තරගයකට පෙර ශරීරය සූදානම් කර ගැනීම සඳහා අනිවාර්යයෙන් කළ යුතු ක්‍රියාවලිය කුමක්ද?", "ශරීරය රත් කිරීම (Warm-up)", "ශරීරය සිසිල් කිරීම", "බර එසවීම", "දිගු නින්දක් ලැබීම", "රත් කිරීම මගින් පේශිවල උෂ්ණත්වය, රුධිර සැපයුම හා සන්ධිවල ලිහිසිකාරක බව වැඩි කරයි."),
        q("ශරීරය රත් කිරීමක (Warm-up) අඩංගු විය යුතු ප්‍රධාන අදියර දෙක මොනවාද?", "සාමාන්‍ය රත් කිරීම සහ විශේෂිත රත් කිරීම", "දිවීම සහ නිදාගැනීම", "බර එසවීම සහ ආහාර ගැනීම", "ස්ථිතික දිගැදීම පමණක්", "සාමාන්‍ය රත් කිරීමෙන් මුළු සිරුරේ උෂ්ණත්වය නංවන අතර විශේෂිත රත් කිරීමෙන් ක්‍රීඩාවට අදාළ පේශි සක්‍රීය කරයි."),
        q("ව්‍යායාමයකට පෙර ශරීරය රත් කිරීම මගින් සිදුවන ප්‍රධානතම සෞඛ්‍යමය වාසිය කුමක්ද?", "මාංශපේශී සහ බන්ධනී ආබාධ (කැඩීම්, ඇදීම්) ඇතිවීමේ අවදානම අවම වීම", "ශරීර බර ක්ෂණිකව අඩුවීම", "පෙනීම වැඩිවීම", "හෘද ස්පන්දනය ශුන්‍ය වීම", "පේශිවල උෂ්ණත්වය ඉහළ යාම නිසා ඒවායේ ප්‍රත්‍යාස්ථතාව වැඩි වී ඉරී යාම් වළකී."),
        q("ක්‍රීඩා පුහුණුවක් අවසානයේ ක්‍රමයෙන් හෘද ස්පන්දනය සාමාන්‍ය තත්ත්වයට ගෙන ඒම සඳහා කළ යුතු ක්‍රියාවලිය කුමක්ද?", "ශරීරය සිසිල් කිරීම හෙවත් ලිහිල් කිරීම (Cool-down)", "ශරීරය රත් කිරීම", "ක්ෂණිකව වාඩිවීම", "අයිස් වතුර ස්නානය", "Cool-down මගින් හෘද ස්පන්දනය ක්‍රමයෙන් අඩු කර ලැක්ටික් අම්ලය බැහැර කිරීම වේගවත් කරයි."),
        q("දැඩි ව්‍යායාමයකින් පසු එකවරම චලනය නතර කර නිශ්චලව වාඩිවීමෙන් හෝ වැතිරීමෙන් සිදුවිය හැකි කරකැවිල්ලට හේතුව කුමක්ද?", "පාදවල රුධිරය එකතැන එකතු වී (Venous Pooling) මොළයට යන රුධිරය අඩුවීම", "රුධිර පීඩනය අධික ලෙස වැඩිවීම", "ශරීරයේ සීනි වැඩිවීම", "පෙනහළු හැකිලීම", "Cool-down කිරීමෙන් පේශි පොම්ප ක්‍රියාකාරිත්වය පවත්වාගෙන ගොස් හදවතට රුධිරය ආපසු ගලා ඒම සුරකියි."),
        q("ශරීරය සිසිල් කිරීමේදී (Cool-down) සිදුකළ යුතු වඩාත්ම සුදුසු දිගැදුම් ව්‍යායාම වර්ගය කුමක්ද?", "ස්ථිතික දිගැදුම් (Static Stretches)", "ක්ෂණික පිමි", "බැලස්ටික් දිගැදුම්", "වේගවත් ධාවනය", "තත්පර 15-30ක් පේශියක් ඇද තබාගෙන සිටින ස්ථිතික දිගැදුම් මගින් පේශි වේදනාව හා තදබව අවම කරයි."),
        q("ඔක්සිජන් ප්‍රමාණවත් ලෙස භාවිත කරමින් දීර්ඝ වේලාවක් සිදුකරන මධ්‍යම තීව්‍රතාවයේ ව්‍යායාම හඳුන්වන්නේ කෙසේද?", "වායුගෝලීය හෙවත් සවායු ව්‍යායාම (Aerobic Exercises)", "නිර්වායු ව්‍යායාම", "සමමිතික ව්‍යායාම", "බැලස්ටික් ව්‍යායාම", "මැරතන් ධාවනය, පිහිනීම, පාපැදි පැදීම සවායු (Aerobic) ව්‍යායාම සඳහා නිදසුන් වේ."),
        q("ඔක්සිජන් නොමැතිව ගබඩා කරගත් ශක්තියෙන් ඉතා කෙටි කාලයකදී උපරිම තීව්‍රතාවයෙන් සිදුකරන ව්‍යායාම මොනවාද?", "නිර්වායු ව්‍යායාම (Anaerobic Exercises)", "සවායු ව්‍යායාම", "විඳදරාගැනීමේ ව්‍යායාම", "ලිහිල් කිරීමේ ව්‍යායාම", "මීටර් 100 ධාවනය, කෙටි පිමි හා බර එසවීම නිර්වායු (Anaerobic) ව්‍යායාම වේ."),
        q("සතියකට දින 5ක් දිනකට මිනිත්තු 30 බැගින් සවායු ව්‍යායාමවල නිරත වීමෙන් වළක්වාගත හැකි බරපතළ සෞඛ්‍ය අවදානම කුමක්ද?", "හෘදයාබාධ, අධික රුධිර පීඩනය සහ දෙවන වර්ගයේ දියවැඩියාව", "බෝවන රෝග පමණි", "අස්ථි බිඳීම් පමණි", "අක්ෂි ආබාධ", "දිනපතා aerobic ව්‍යායාම මගින් හෘද වාහිනී පද්ධතිය ශක්තිමත් කර රුධිර පීඩනය හා සීනි මට්ටම පාලනය කරයි."),
        q("කිසිදු විවේක කාලයක් නොමැතිව එකම වේගයකින් දිගු වේලාවක් (මිනිත්තු 20කට වඩා) සිදුකරන පුහුණු ක්‍රමය කුමක්ද?", "අඛණ්ඩ පුහුණු ක්‍රමය (Continuous Training)", "අන්තරාල පුහුණුව", "පරිපථ පුහුණුව", "ප්ලයොමෙට්‍රික් පුහුණුව", "අඛණ්ඩ පුහුණුව මගින් සවායු ධාරිතාව හා හෘද ස්වසන විඳදරාගැනීම විශිෂ්ට ලෙස වර්ධනය කරයි."),
        q("වැඩ කාලසීමාවක් සහ නියමිත සහනදායී විවේක කාලසීමාවක් (Work : Rest) මාරුවෙන් මාරුවට යොදාගන්නා පුහුණු ක්‍රමය කුමක්ද?", "අන්තරාල පුහුණු ක්‍රමය (Interval Training)", "අඛණ්ඩ පුහුණුව", "ස්ථිතික පුහුණුව", "නම්‍යශීලී පුහුණුව", "උදාහරණයක් ලෙස තත්පර 30ක අධිවේගී දිවීම සහ තත්පර 60ක ඇවිදීමේ විවේකය මාරුවෙන් මාරුවට සිදුකිරීමයි."),
        q("ස්වීඩන් බසින් 'වේග ක්‍රීඩාව' (Speed Play) ලෙස හඳුන්වන, ස්වාභාවික පරිසරයේ කඳු හා බෑවුම් ඔස්සේ වේගය වෙනස් කරමින් දුවන ක්‍රමය කුමක්ද?", "ෆාට්ලෙක් පුහුණු ක්‍රමය (Fartlek Training)", "පරිපථ පුහුණුව", "බර පුහුණුව", "අයිසොමෙට්‍රික් පුහුණුව", "ගෝස්ටා හෝල්මර් විසින් හඳුන්වා දුන් ෆාට්ලෙක් ක්‍රමයේදී ධාවකයා තම අභිමතය පරිදි වේගය වෙනස් කරමින් දිව යයි."),
        q("ක්‍රීඩාංගණයේ විවිධ ස්ථානවල (Stations 6-10) සකස් කළ වෙනස් ව්‍යායාම අනුපිළිවෙළින් සිදුකරන පුහුණු ක්‍රමය කුමක්ද?", "පරිපථ පුහුණු ක්‍රමය (Circuit Training)", "අඛණ්ඩ පුහුණුව", "ප්ලයොමෙට්‍රික් පුහුණුව", "ෆාට්ලෙක් පුහුණුව", "පරිපථ පුහුණුවේදී එක් පේශි කාණ්ඩයක් වෙහෙස වූ පසු ඊළඟ ස්ථානයේදී වෙනත් පේශි කාණ්ඩයකට ව්‍යායාම ලැබේ."),
        q("මාංශපේශී ප්‍රථමයෙන් ක්ෂණිකව දිගහැර වහාම පුපුරන සුලු බලයකින් හැකිලීම මගින් ජවය වර්ධනය කරන පිමි පුහුණු ක්‍රමය කුමක්ද?", "ප්ලයොමෙට්‍රික් පුහුණු ක්‍රමය (Plyometric Training)", "අඛණ්ඩ පුහුණුව", "ස්ථිතික පුහුණුව", "සමමිතික පුහුණුව", "පෙට්ටි මතින් පැනීම (Box Jumps) හා ගැඹුරු පිමි (Depth Jumps) ප්ලයොමෙට්‍රික් පුහුණුවට ප්‍රකට නිදසුන් වේ."),
        q("මාංශපේශීවල ප්‍රමාණය (Hypertrophy) සහ උපරිම ශක්තිය වර්ධනය කර ගැනීම සඳහා බර යොදාගන්නා පුහුණු ක්‍රමය කුමක්ද?", "ප්‍රතිරෝධක හෙවත් බර පුහුණු ක්‍රමය (Weight / Resistance Training)", "ෆාට්ලෙක් පුහුණුව", "සවායු පුහුණුව", "නම්‍යශීලී පුහුණුව", "ඩම්බල්, බාබෙල් සහ බර යන්ත්‍ර යොදාගනිමින් නිශ්චිත පුනරාවර්තන (Reps) සහ කට්ටල (Sets) අනුව පුහුණු වේ."),
        q("බර පුහුණුවේදී මාංශපේශී උපරිම ශක්තිය වර්ධනය කර ගැනීම සඳහා නිර්දේශිත පුනරාවර්තන (Reps) පරාසය කුමක්ද?", "අධික බරක් යොදා පුනරාවර්තන 1 සිට 6 දක්වා", "ඉතා අඩු බරකින් පුනරාවර්තන 30ක්", "පුනරාවර්තන 100ක්", "එක් වතාවක් පමණි", "උපරිම ශක්තිය සඳහා 85%කට වඩා වැඩි බරකින් අඩු පුනරාවර්තන (1-6 Reps) සිදුකළ යුතුය."),
        q("බර පුහුණුවේදී මාංශපේශී විඳදරාගැනීම (Muscular Endurance) වර්ධනය කර ගැනීමට සුදුසු පුනරාවර්තන සංඛ්‍යාව කුමක්ද?", "මධ්‍යම හෝ අඩු බරකින් වැඩි පුනරාවර්තන 15 සිට 20 දක්වා", "උපරිම බරකින් පුනරාවර්තන 1ක්", "පුනරාවර්තන 2ක් පමණි", "බර රහිතව", "විඳදරාගැනීම සඳහා සැහැල්ලු බරකින් වැඩි වාර ගණනක් (15-20+ Reps) පේශි හැකිලීම සිදුකරයි."),
        q("චලනය වෙමින් සන්ධිවල පූර්ණ චලන පරාසය ප්‍රයෝජනයට ගනිමින් ශරීරය රත් කිරීම සඳහා සිදුකරන දිගැදුම් ක්‍රමය කුමක්ද?", "ගතික දිගැදුම් (Dynamic Stretching)", "ස්ථිතික දිගැදුම්", "නිෂ්ක්‍රීය දිගැදුම්", "සමමිතික දිගැදුම්", "පාද පැද්දීම, අත් කරකැවීම, ලන්ජස් වැනි ගතික දිගැදුම් මගින් පේශි සක්‍රීය කර ක්‍රීඩාවට සූදානම් කරයි."),
        q("පුහුණු සහායකයෙකුගේ ආධාරයෙන් පේශියක් හැකිලීම සහ ලිහිල් කිරීම මාරුවෙන් මාරුවට යොදාගන්නා උසස් නම්‍යශීලීතා ක්‍රමය කුමක්ද?", "PNF දිගැදුම් ක්‍රමය (Proprioceptive Neuromuscular Facilitation)", "බැලස්ටික් දිගැදුම්", "ගතික දිගැදුම්", "සාමාන්‍ය දිගැදුම්", "PNF ක්‍රමයේදී ස්නායු ප්‍රතිචාර ලිහිල් කරමින් සන්ධියක උපරිම නම්‍යශීලීතාවක් ලබාගත හැක."),
        q("ක්‍රීඩකයෙකුගේ වාර්ෂික පුහුණු සැලැස්ම අදියර කිහිපයකට ක්‍රමානුකූලව බෙදා වෙන් කිරීමේ ක්‍රියාවලිය කුමක්ද?", "කාලාවර්තනය (Periodization)", "අතිභාරය", "ප්‍රතිවර්ත්‍යතාව", "FITT ක්‍රමය", "කාලාවර්තනය මගින් තරග සමයේදී ක්‍රීඩකයා උපරිම කාර්යසාධන මට්ටමට (Peaking) ගෙන ඒම තහවුරු කරයි."),
        q("වාර්ෂික පුහුණු සැලැස්මක සමස්ත වසරම ආවරණය වන දිගුකාලීන පුහුණු චක්‍රය හඳුන්වන්නේ කෙසේද?", "මැක්‍රෝචක්‍රය (Macrocycle)", "මෙසෝචක්‍රය", "මයික්‍රෝචක්‍රය", "දෛනික චක්‍රය", "මැක්‍රෝචක්‍රය සාමාන්‍යයෙන් මාස කිහිපයක සිට වසරක් හෝ ඔලිම්පික් වසර 4ක කාලයක් විය හැක."),
        q("සාමාන්‍යයෙන් සති 2 සිට සති 6 දක්වා කාලයක් පුරා විශේෂිත යෝග්‍යතා අරමුණක් වෙනුවෙන් පවත්වන මධ්‍යම ප්‍රමාණයේ පුහුණු චක්‍රය කුමක්ද?", "මෙසෝචක්‍රය (Mesocycle)", "මැක්‍රෝචක්‍රය", "මයික්‍රෝචක්‍රය", "නැනෝචක්‍රය", "මෙසෝචක්‍රයක් මගින් ශක්ති වර්ධනය, වේගය හෝ තාක්ෂණික කුසලතා දියුණු කිරීම ඉලක්ක කරයි."),
        q("දින කිහිපයක සිට සතියක් (දින 7ක්) දක්වා කාලසීමාවක් ආවරණය වන කෙටිම පුහුණු සැලසුම් චක්‍රය කුමක්ද?", "මයික්‍රෝචක්‍රය (Microcycle)", "මැක්‍රෝචක්‍රය", "මෙසෝචක්‍රය", "වාර්ෂික චක්‍රය", "මයික්‍රෝචක්‍රය යනු සතිපතා දෛනික පුහුණු සැසි හා විවේක දින සැලසුම් කරන ඒකකයයි."),
        q("වාර්ෂික පුහුණු සැලැස්මක තරගාවලියට පෙර සාමාන්‍ය සහ විශේෂිත යෝග්‍යතාව ගොඩනගන ප්‍රධානතම අදියර කුමක්ද?", "සූදානම් වීමේ අදියර (Preparation Phase)", "තරගකාරී අදියර", "සංක්‍රාන්ති අදියර", "විවේක අදියර පමණක්", "සූදානම් වීමේ අදියරේදී ශරීරයේ මූලික ශක්තිය, විඳදරාගැනීම සහ මූලික කුසලතා වර්ධනය කෙරේ."),
        q("ක්‍රීඩකයා ප්‍රධාන තරග සඳහා ඉදිරිපත් වන, උපරිම කාර්යසාධනයක් අපේක්ෂා කරන අදියර කුමක්ද?", "තරගකාරී අදියර (Competition Phase)", "සූදානම් වීමේ අදියර", "සංක්‍රාන්ති අදියර", "මූලික අදියර", "මෙම අදියරේදී පුහුණු පරිමාව අඩු කර තීව්‍රතාව උපරිම මට්ටමේ පවත්වා ගනිමින් ජයග්‍රහණය ඉලක්ක කරයි."),
        q("තරග වාරය අවසන් වීමෙන් පසු ශාරීරික හා මානසික විඩාව දුරු කරමින් ක්‍රියාකාරී විවේකයක් ලබන අදියර කුමක්ද?", "සංක්‍රාන්ති අදියර (Transition Phase / Off-season)", "තරගකාරී අදියර", "සූදානම් වීමේ අදියර", "අතිභාර අදියර", "ක්‍රියාකාරී විවේකය (Active rest) මගින් ආබාධ සුව කරගනිමින් ඊළඟ වසර සඳහා ශරීරය සූදානම් කරයි."),
        q("ප්‍රමාණවත් විවේකයක් හා පෝෂණයක් නොමැතිව දිගින් දිගටම අධික ලෙස පුහුණුවීම් කිරීම නිසා ක්‍රීඩා දක්ෂතා පහත වැටීම හඳුන්වන්නේ කෙසේද?", "අධිපුහුණු සහලක්ෂණය (Overtraining Syndrome)", "සුපිරි වන්දි ගෙවීම", "අතිභාරය", "විශිෂ්ටතාව", "අධිපුහුණුව නිසා නිදන්ගත තෙහෙට්ටුව, නින්ද නොයාම, මානසික අවපීඩනය හා නිතර ආබාධ ඇතිවේ."),
        q("අධිපුහුණු සහලක්ෂණයේ (Overtraining) ප්‍රධානතම කායික අනතුරු ඇඟවීමේ ලක්ෂණයක් වන්නේ කුමක්ද?", "උදෑසන අවදි වූ වහාම මනින විවේකී හෘද ස්පන්දන වේගය අසාමාන්‍ය ලෙස ඉහළ යාම", "ශරීර බර එකවර වැඩිවීම", "ක්‍රීඩා දක්ෂතා ඉහළ යාම", "හෘද ස්පන්දනය අඩුවීම", "විවේකී හෘද ස්පන්දනය සාමාන්‍ය මට්ටමට වඩා 10-15 bpm කින් වැඩිවීම ශරීරය විවේකය ඉල්ලන බවට ලකුණකි."),
        q("පුහුණු සැසියකට පසු විවේකයේදී ශරීරය පෙර තිබූ මට්ටමට වඩා ඉහළ යෝග්‍යතා මට්ටමකට ළඟාවීමේ ජීව විද්‍යාත්මක සංසිද්ධිය කුමක්ද?", "සුපිරි වන්දි ගෙවීම (Supercompensation)", "ප්‍රතිවර්ත්‍යතාව", "අධිපුහුණුව", "ක්ෂය වීම", "නිසි විවේකය හා පෝෂණය ලැබුණු විට ශරීරය පෙරට වඩා ශක්තිමත් වී නව උසස් මට්ටමකට පැමිණේ."),
        q("පුද්ගලයෙකු නව ව්‍යායාම වැඩසටහනක් ආරම්භ කිරීමට පෙර ඔහුගේ සෞඛ්‍ය අවදානම් තක්සේරු කිරීමට යොදාගන්නා සම්මත ප්‍රශ්නාවලිය කුමක්ද?", "කායික ක්‍රියාකාරකම් සූදානම්තා ප්‍රශ්නාවලිය (PAR-Q)", "BMI ප්‍රශ්නාවලිය", "ක්‍රීඩා වාර්තාව", "පාසල් අයදුම්පත", "Physical Activity Readiness Questionnaire මගින් හෘද රෝග, සන්ධි ආබාධ ආදිය පරීක්ෂා කරයි."),
        q("පාසල් මට්ටමේ ශාරීරික යෝග්‍යතා පරීක්ෂණ පැවැත්වීමේ ප්‍රධානතම අධ්‍යාපනික හා සෞඛ්‍යමය අරමුණ කුමක්ද?", "සිසුන්ගේ වත්මන් යෝග්‍යතා මට්ටම හඳුනාගෙන දුර්වලතා මඟහරවා ගැනීමට මඟපෙන්වීම", "දුර්වල සිසුන්ට දඬුවම් කිරීම", "සිසුන් ශ්‍රේණිගත කර තරගයෙන් ඉවත් කිරීම", "ක්‍රීඩා නොකරන ලෙස දැන්වීම", "යෝග්‍යතා පරීක්ෂණ මගින් ශිෂ්‍යයාගේ සෞඛ්‍ය සම්පන්න වර්ධනයට අවශ්‍ය සැලසුම් සකස් කෙරේ."),
        q("ක්‍රීඩකයෙකුගේ උපරිම ඔක්සිජන් පරිභෝජන ධාරිතාව හඳුන්වන විද්‍යාත්මක සංකේතය කුමක්ද?", "VO2 max", "BMI", "BMR", "HR max", "VO2 max යනු උපරිම ව්‍යායාමයකදී මිනිත්තුවකට කිලෝග්‍රෑමයකට දේහයට පරිභෝජනය කළ හැකි උපරිම ඔක්සිජන් මිලිලීටර් ප්‍රමාණයයි."),
        q("වයස අවුරුදු 15ක සිසුවෙකුගේ ඉලක්කගත හෘද ස්පන්දන කලාපයේ (60% - 85%) පහළ සීමාව මිනිත්තුවට ස්පන්දන කීයද?", "මිනිත්තුවට වාර 123ක් පමණ (205 × 0.60)", "මිනිත්තුවට වාර 60ක්", "මිනිත්තුවට වාර 180ක්", "මිනිත්තුවට වාර 90ක්", "MHR = 220 - 15 = 205 bpm. එහි 60% = 123 bpm වේ."),
        q("වයස අවුරුදු 15ක සිසුවෙකුගේ ඉලක්කගත හෘද ස්පන්දන කලාපයේ (85%) ඉහළ සීමාව ආසන්න වශයෙන් කීයද?", "මිනිත්තුවට වාර 174ක් පමණ (205 × 0.85)", "මිනිත්තුවට වාර 220ක්", "මිනිත්තුවට වාර 140ක්", "මිනිත්තුවට වාර 200ක්", "MHR 205 කින් 85% ක් යනු ආසන්න වශයෙන් මිනිත්තුවට වාර 174කි."),
        q("අධික ලෙස බර එසවීමේදී හුස්ම තද කරගෙන බඩ තද කර පීඩනය වැඩි කිරීමෙන් ක්ලාන්තය ඇතිවිය හැකි භයානක තත්ත්වය කුමක්ද?", "වල්සල්වා උපාමාරුව (Valsalva Maneuver)", "ඔක්සිජන් ණය", "සුපිරි වන්දි ගෙවීම", "හයිපොතර්මියාව", "හුස්ම හිරකරගෙන බර එසවීමේදී උරස් කුහරයේ පීඩනය වැඩි වී හදවතට රුධිර ගමන අඩාල වී ක්ලාන්තය ඇතිවේ."),
        q("බර එසවීමේ ව්‍යායාමවලදී හුස්ම ගැනීමේ නිවැරදි විද්‍යාත්මක පිළිවෙත කුමක්ද?", "බර එසවීමේදී (වෙහෙසෙන විට) ප්‍රශ්වාස කිරීම සහ බර පහත් කිරීමේදී ආශ්වාස කිරීම", "මුළු කාලය පුරාම හුස්ම තද කරගෙන සිටීම", "බර එසවීමේදී පමණක් වේගයෙන් ආශ්වාස කිරීම", "කිසිසේත් හුස්ම නොගැනීම", "වෙහෙසෙන අවස්ථාවේදී හුස්ම පිටකිරීමෙන් (Exhale on exertion) රුධිර පීඩනය අනතුරුදායක ලෙස ඉහළ යාම වළකී."),
        q("නම්‍යශීලීතාව වර්ධනය කර ගැනීම සඳහා ස්ථිතික දිගැදුමකදී එක් ඉරියව්වක් අවම වශයෙන් තත්පර කීයක් රඳවා තබාගත යුතුද?", "තත්පර 15 සිට 30 දක්වා", "තත්පර 2ක් පමණි", "මිනිත්තු 30ක්", "තත්පර 5ක්", "තත්පර 15-30ක් පේශියක් ඇද තබා ගැනීමෙන් පේශි දඟර (Muscle spindles) ලිහිල් වී සන්ධි චලන පරාසය වැඩිවේ."),
        q("ක්‍රීඩකයෙකුගේ යෝග්‍යතා මට්ටම ඉහළ යාමේදී ඔහුගේ 'විවේකී හෘද ස්පන්දන වේගයට' (Resting Heart Rate) සිදුවන්නේ කුමක්ද?", "විවේකී හෘද ස්පන්දන වේගය ක්‍රමයෙන් අඩුවේ", "විවේකී හෘද ස්පන්දන වේගය වැඩිවේ", "කිසිදු වෙනසක් සිදු නොවේ", "අක්‍රමවත් වේ", "හෘදයේ පහර පරිමාව වැඩිවීම නිසා හදවතට අඩු වාර ගණනකින් ශරීරයට අවශ්‍ය රුධිරය සැපයිය හැක."),
        q("යෝග්‍යතා සංවර්ධනයේදී 'ක්‍රියාකාරී සුවය ලැබීම' (Active Recovery) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දැඩි පුහුණු දිනයකට පසු දින ඉතා සැහැල්ලු ඇවිදීමක් හෝ පිහිනීමක් මගින් රුධිර සංසරණය පවත්වා ගනිමින් සුවය ලැබීම", "දවස පුරාම නිදාගැනීම පමණක්", "අඛණ්ඩව දැඩි බර එසවීම", "ආහාර නොගෙන සිටීම", "සැහැල්ලු ව්‍යායාම මගින් පේශිවල තැන්පත් අපද්‍රව්‍ය ඉවත් වීම වේගවත් කරයි."),
        q("හෘද ස්වසන යෝග්‍යතාවය දුර්වල පුද්ගලයෙකුට පඩිපෙළක් නගින විට හෝ සුළු දුරක් දුවන විට ඇතිවන ක්ෂණික අපහසුතාව කුමක්ද?", "අධික හතිය, පපුවේ තදබව සහ ක්ෂණික තෙහෙට්ටුව", "ශරීර උෂ්ණත්වය පහත වැටීම", "අත් පා හිරිවැටීම පමණි", "බඩගින්න වැඩිවීම", "හෘදය හා පෙනහළුවලට අවශ්‍ය ඔක්සිජන් සක්‍රීය පේශි වෙත ප්‍රමාණවත් ලෙස සැපයිය නොහැකි වීම නිසා හතිය හටගනී."),
        q("යෝග්‍යතා පුහුණුවකදී 'ප්‍රතිරෝධය' (Resistance) ලෙස යොදාගත හැක්කේ පහත සඳහන් කවරක්ද?", "තමන්ගේම ශරීර බර, ඩම්බල්/බාබෙල්, ප්‍රත්‍යාස්ථ පටි හෝ ජලයේ ප්‍රතිරෝධය", "හිස් අතින් පමණක් සිටීම", "සුළඟ පමණි", "ක්‍රීඩා සපත්තු පමණි", "ශරීර බර යොදාගන්නා පුෂ්-අප්ස්, පුල්-අප්ස් මෙන්ම බාහිර බරද ප්‍රතිරෝධය ලෙස යොදාගත හැක."),
        q("ශරීරයේ කඳ කොටස (උදරය, කොන්ද හා ශ්‍රෝණිය) ශක්තිමත් කරන Core Stability ව්‍යායාමයකට ප්‍රකට නිදසුනක් කුමක්ද?", "ප්ලෑන්ක් ව්‍යායාමය (Plank Exercise)", "කෙටි දුර ධාවනය", "යගුලිය දැමීම", "උස පැනීම", "ප්ලෑන්ක් මගින් කොඳු ඇට පෙළ වටා ඇති ගැඹුරු පේශි ශක්තිමත් කර නිවැරදි ඉරියව්ව හා සමබරතාව සුරකියි."),
        q("වයස්ගත වීමත් සමග මාංශපේශී ස්කන්ධය සහ ශක්තිය ක්‍රමයෙන් ක්ෂය වී යාමේ ස්වාභාවික ක්‍රියාවලිය කුමක්ද?", "සාකොපීනියාව (Sarcopenia)", "ඔස්ටියෝපොරෝසිස්", "ආතරයිටිස්", "ස්කෝලියෝසිස්", "නිතිපතා ප්‍රතිරෝධක ව්‍යායාමවල නිරත වීමෙන් සාකොපීනියාව සාර්ථකව පාලනය කරගත හැක."),
        q("නිරෝගී වැඩිහිටියෙකුගේ සාමාන්‍ය ශරීර මේද ප්‍රතිශතය (Body Fat Percentage) පිරිමින් සහ කාන්තාවන් සඳහා පිළිවෙළින් කුමන පරාසයක පවතීද?", "පිරිමින් 10%-20% අතර සහ කාන්තාවන් 18%-28% අතර", "දෙපිරිසටම 50%කට වැඩි", "පිරිමින් 2%ක් සහ කාන්තාවන් 5%ක්", "දෙපිරිසටම 0%ක්", "ප්‍රජනක හා හෝමෝන අවශ්‍යතා නිසා කාන්තාවන්ගේ අත්‍යවශ්‍ය මේද ප්‍රතිශතය පිරිමින්ට වඩා මඳක් ඉහළය."),
        q("ළමුන් සහ යෞවනයන් දිනපතා අවම වශයෙන් මධ්‍යම හෝ දැඩි තීව්‍රතාවයේ ශාරීරික ක්‍රියාකාරකම්වල කොපමණ වේලාවක් නිරත විය යුතු බව ලෝක සෞඛ්‍ය සංවිධානය නිර්දේශ කරයිද?", "දිනකට අවම වශයෙන් මිනිත්තු 60ක් (පැය 1ක්)", "දිනකට මිනිත්තු 5ක්", "සතියකට පැය භාගයක් පමණි", "මසකට එක් දිනක්", "දිනපතා පැයක කායික ක්‍රියාකාරකම් ළමා අස්ථි, පේශි හා මානසික සුවතාවට අත්‍යවශ්‍ය වේ."),
        q("ශාරීරික යෝග්‍යතාව ඉහළ මට්ටමක පවත්වා ගැනීමෙන් පාසල් සිසුන්ගේ අධ්‍යාපනික කාර්යසාධනයට ලැබෙන පිටුවහල කුමක්ද?", "මොළයට රුධිර සැපයුම වැඩි වී අවධානය, මතක ශක්තිය හා ඉගෙනුම් ධාරිතාව ඉහළ යාම", "පාඩම් කිරීමට ඇති කාලය සම්පූර්ණයෙන් නැතිවීම", "නිතර නින්ද යාම", "පොත් කියවීමට නොහැකි වීම", "ව්‍යායාම මගින් මොළයේ BDNF හෝමෝනය නිපදවීම උත්තේජනය වී බුද්ධි වර්ධනයට මඟ පාදයි."),
        q("පාසල් ක්‍රීඩකයෙකුගේ යෝග්‍යතා වාර්තාවල ප්‍රගතිය සටහන් කර තබාගැනීම වැදගත් වන්නේ ඇයි?", "පුහුණු වැඩසටහනේ සාර්ථකත්වය ඇගයීමට සහ අනාගත ඉලක්ක නිවැරදිව සැලසුම් කිරීමට", "අනෙක් ළමුන්ට අපහාස කිරීමට", "වාර්තා පුස්තකාලයේ තැන්පත් කිරීමට පමණක්", "ලකුණු අඩු කිරීමට", "දත්ත පදනම් කරගත් පුහුණුව මගින් ක්‍රීඩකයාගේ දුර්වලතා හඳුනාගෙන ක්‍රමානුකූලව දක්ෂතා ඔපමට්ටම් කළ හැක."),
        q("ක්‍රීඩා පුහුණුවකදී සිදුවිය හැකි අනතුරු හා ආබාධ වළක්වා ගැනීමට උපකාරී වන ප්‍රධානතම පුහුණු පියවර කුමක්ද?", "ක්‍රමානුකූලව ශරීරය රත් කිරීම, නිවැරදි තාක්ෂණය භාවිතය සහ සුදුසු ආරක්ෂක ආම්පන්න පැළඳීම", "හැකි උපරිම වේගයෙන් එකවරම ක්‍රීඩා කිරීම", "ආරක්ෂක ආම්පන්න නොමැතිව පුහුණු වීම", "වෙහෙස නොබලා දින ගණනක් නොකඩවා ක්‍රීඩා කිරීම", "නිසි රත් කිරීම හා ආරක්ෂක උපකරණ මගින් ක්‍රීඩා අනතුරු 80% කින් පමණ වළක්වාගත හැක."),
        q("ක්‍රීඩකයෙකුට ප්‍රමාණවත් නින්දක් (දිනකට පැය 8-9ක්) නොලැබීමෙන් ඔහුගේ ශාරීරික යෝග්‍යතාවට සිදුවන ක්ෂණික බලපෑම කුමක්ද?", "ප්‍රතිචාර කාලය මන්දගාමී වීම, තෙහෙට්ටුව සහ ආබාධ ඇතිවීමේ අවදානම ඉහළ යාම", "වේගය දෙගුණ වීම", "පේශි ශක්තිය වැඩිවීම", "නම්‍යශීලීතාව ඉහළ යාම", "නින්ද නොමැති විට මොළයේ අවධානය ගිලිහී පේශිවලට අවශ්‍ය වර්ධක හෝමෝන ශ්‍රාවය වීම අඩාල වේ."),
        q("ක්‍රීඩකයෙකු දිගු කලක් එකම තීව්‍රතාවයකින් සහ එකම බරකින් පුහුණු වීම නිසා යෝග්‍යතාව තවදුරටත් වර්ධනය නොවී එකතැන පල්වීම හඳුන්වන්නේ කෙසේද?", "සානුවකට ළඟාවීම හෙවත් එකතැන පල්වීම (Plateau)", "අධිපුහුණුව", "ප්‍රතිවර්ත්‍යතාව", "සුපිරි වන්දි ගෙවීම", "ප්ලැටෝ තත්ත්වය බිඳහෙළීමට නම් අතිභාරය හෝ පුහුණු විවිධත්වය වෙනස් කළ යුතුය."),
        q("යෝග්‍යතා පුහුණු සැසියක් ආරම්භ කළ යුතු සහ අවසන් කළ යුතු සම්මත අනුපිළිවෙළ කුමක්ද?", "රත් කිරීම — ප්‍රධාන පුහුණු සැසිය — සිසිල් වීම", "ප්‍රධාන සැසිය — රත් කිරීම — සිසිල් වීම", "සිසිල් වීම — රත් කිරීම — ප්‍රධාන සැසිය", "ප්‍රධාන සැසිය පමණි", "මෙම සම්මත ත්‍රිත්ව අනුපිළිවෙළ අනුගමනය කිරීම ආරක්ෂිත හා විද්‍යාත්මක පුහුණුවක පදනමයි."),
        q("ක්‍රීඩා පුහුණුවේදී විජලනය වීම වැළැක්වීම සඳහා ක්‍රීඩකයෙකු පිපාසය දැනෙන තෙක් නොසිට කළ යුත්තේ කුමක්ද?", "පුහුණුවට පෙර, අතරතුර සහ පසුව නියමිත කාල පරතරයන්හිදී සුළු වශයෙන් ජලය පානය කිරීම", "පුහුණුව අවසන් වන තුරුම වතුර නොබී සිටීම", "එකවර ජලය ලීටර් ගණනක් පානය කිරීම", "පැණිබීම පමණක් පානය කිරීම", "පිපාසය දැනෙන විටත් ශරීරය 1-2% කින් විජලනය වී ඇති බැවින් කාලසටහනකට අනුව ජලය පානය කළ යුතුය."),
        q("ක්‍රීඩකයෙකුගේ යෝග්‍යතාව මැන බැලීමේදී 'විශ්වසනීයත්වය' (Reliability) යන්නෙන් අදහස් වන්නේ කුමක්ද?", "එකම තත්ත්වයන් යටතේ පරීක්ෂණය නැවත නැවත සිදුකළද එකම ප්‍රතිඵලයක් ලැබීමේ හැකියාව", "පරීක්ෂණය ඉතා පහසු වීම", "පරීක්ෂණයට අඩු කාලයක් ගතවීම", "ඕනෑම අයෙකුට ජයගත හැකි වීම", "විශ්වසනීය පරීක්ෂණයකින් නිරන්තරයෙන්ම නිවැරදි හා ස්ථාවර මිනුම් ලබාගත හැක."),
        q("යෝග්‍යතා පරීක්ෂණයක 'වලංගුභාවය' (Validity) යන්නෙන් අදහස් වන්නේ කුමක්ද?", "පරීක්ෂණය මගින් මැනීමට අපේක්ෂා කරන නිශ්චිත යෝග්‍යතා සංඝටකයම එයින් මනිනු ලබන්නේද යන්න", "පරීක්ෂණයේ වියදම අඩු වීම", "පරීක්ෂණ උපකරණ ලස්සන වීම", "සියලු දෙනාම සමත් වීම", "නිදසුනක් ලෙස වේගය මැනීමට මීටර් 50 ධාවනය වලංගු පරීක්ෂණයක් වන නමුත් නම්‍යශීලීතාව මැනීමට එය වලංගු නොවේ.")
    )
}
